"""Build a presentation-only D3 executive dashboard from consolidated evidence."""
from pathlib import Path
import hashlib,json,html
from datetime import datetime,timezone
BASE=Path(__file__).resolve().parent; OUT=BASE/"outputs"; OUT.mkdir(parents=True,exist_ok=True)
REPO="https://github.com/elizabethhannan/Anthropic_Greenhouse_ATS_AI_Biased"
evidence_path=OUT/"executive_evidence_v3.json"
data=json.loads(evidence_path.read_text(encoding="utf-8"))
if data["observed_outcomes"] != {"male":606,"female":276,"unknown":213,"total":1095,"known_sex_n":882,"male_share_known":606/882,"female_share_known":276/882,"male_female_ratio":606/276}:
    raise ValueError("Consolidated outcome evidence differs from frozen canonical values")
payload=json.dumps(data,ensure_ascii=False).replace("</","<\\/")
question=html.escape(data["executive_question"])
doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Version C — Executive Evidence Dashboard</title>
<script src="https://d3js.org/d3.v7.min.js"></script>
<style>
:root{{--cream:#f5f1e8;--panel:#fbfaf6;--navy:#12203c;--muted:#586579;--green:#547a47;--blue:#547ca8;--red:#b95a4c;--gold:#b4933e;--line:#e0d9cc;--shadow:rgba(27,37,55,.12)}}*{{box-sizing:border-box}}body{{margin:0;background:var(--cream);color:var(--navy);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}}main{{max-width:1180px;margin:auto;padding:36px 24px 60px}}.eyebrow{{text-transform:uppercase;letter-spacing:.12em;font-size:12px;color:var(--green);font-weight:800}}h1{{font-size:clamp(27px,4vw,44px);line-height:1.1;max-width:1000px;margin:12px 0 16px}}h2{{font-size:20px;margin:0 0 14px}}.sub{{color:var(--muted);max-width:900px}}.hold{{display:inline-block;background:#f5e8be;color:#594615;padding:8px 13px;border-radius:999px;font-weight:800;font-size:12px;letter-spacing:.04em}}.grid{{display:grid;gap:16px}}.metrics{{grid-template-columns:repeat(4,minmax(0,1fr));margin:24px 0}}.cols{{grid-template-columns:1.1fr .9fr;margin-top:16px}}.card{{background:var(--panel);border:1px solid white;border-radius:20px;padding:22px;box-shadow:8px 8px 22px var(--shadow),-6px -6px 17px rgba(255,255,255,.8)}}.metric .value{{font-size:36px;font-weight:850;letter-spacing:-.04em}}.metric .label{{font-weight:750;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.07em}}.metric .note{{font-size:13px;color:var(--muted)}}.ratio{{font-weight:800;color:var(--green);font-size:24px}}.caveat{{border-left:5px solid var(--gold);padding:14px 17px;background:#f7f0dc;border-radius:0 12px 12px 0;margin:20px 0}}.pillars{{grid-template-columns:repeat(3,1fr);margin:16px 0}}.pillar{{min-height:150px}}.tag{{font-size:11px;letter-spacing:.08em;font-weight:850}}.pillar h3{{margin:7px 0;font-size:22px}}.pillar p{{margin:0;color:var(--muted)}}.signal{{color:var(--green)}}.prediction{{color:var(--red)}}.feedback{{color:var(--blue)}}.chart{{width:100%;min-height:215px}}.boundary{{font-size:14px;color:var(--muted)}}.thesis{{font-size:20px;font-weight:720;max-width:930px}}.foot{{font-size:12px;color:var(--muted);margin-top:22px;border-top:1px solid var(--line);padding-top:16px}}ul{{padding-left:20px;color:var(--muted)}}a{{color:var(--blue)}}@media(max-width:760px){{.metrics{{grid-template-columns:repeat(2,1fr)}}.cols,.pillars{{grid-template-columns:1fr}}main{{padding:24px 16px}}}}
</style></head><body><main>
<div class="eyebrow">Version C · Version 3.0 · Executive review</div><h1>{question}</h1>
<p class="sub">Public evidence shows an observed representation disparity, but cannot locate where it emerges within the AI-assisted employment system.</p><span class="hold">PUBLICATION STATUS: HOLD / REVIEW REQUIRED</span>
<section class="grid metrics" aria-label="Observed hiring outcomes">
<article class="card metric"><div class="label">Observed people</div><div class="value">1,095</div><div class="note">Available public outcome records</div></article>
<article class="card metric"><div class="label">Male</div><div class="value">606</div><div class="note">68.7% of known-sex records</div></article>
<article class="card metric"><div class="label">Female</div><div class="value">276</div><div class="note">31.3% of known-sex records</div></article>
<article class="card metric"><div class="label">Unknown</div><div class="value">213</div><div class="note">Retained as Unknown</div></article></section>
<div class="card"><strong>Known-sex composition:</strong> 68.7% Male · 31.3% Female &nbsp; <span class="ratio">2.20 : 1</span> observed Male/Female ratio<div id="outcome-chart" class="chart" role="img" aria-label="Observed outcomes by reported sex category"></div></div>
<div class="caveat"><strong>Interpretation boundary.</strong> This is an observed outcome disparity in the available public data. It does not establish that Greenhouse caused the disparity.</div>
<section class="grid pillars"><article class="card pillar"><div class="tag signal">DIAGNOSTIC 01</div><h3>SIGNAL</h3><strong class="signal">OBSERVABLE</strong><p>Public posting content can be described. Lexical measures do not establish preference, intent, or discrimination.</p></article><article class="card pillar"><div class="tag prediction">DIAGNOSTIC 02</div><h3>PREDICTION</h3><strong class="prediction">NOT ESTIMABLE FROM PUBLIC DATA</strong><p>Only 3 eligible matched role/month cells; no Female outcome cells. No model was fit.</p></article><article class="card pillar"><div class="tag feedback">DIAGNOSTIC 03</div><h3>FEEDBACK</h3><strong class="feedback">EXPLORATORY</strong><p>Coverage limits and small temporal samples prevent strong conclusions.</p></article></section>
<section class="grid cols"><article class="card"><h2>Evidence coverage</h2><div id="posting-chart" class="chart" role="img" aria-label="Greenhouse posting date evidence categories"></div><p class="boundary">1,246 postings total: 514 with established dates in the study window, 617 archive-capture-only, and 115 outside the window. Archive capture is not treated as posting date.</p></article><article class="card"><h2>Executive proposition</h2><p class="thesis">MODEL FAIRNESS ≠ WORKFLOW FAIRNESS ≠ OUTCOME FAIRNESS</p><p>Proposed function: <strong>Human-AI Employment Intelligence &amp; Governance</strong></p><p class="boundary">The public evidence identifies a material question and an instrumentation gap. Internal stage-level data are required to locate mechanisms and evaluate interventions.</p><h2>Controls</h2><ul><li>No sex inference; Unknown remains Unknown</li><li>No candidate-level Greenhouse-to-hire linkage</li><li>No synthetic candidates or applicant denominators</li><li>No unsupported Greenhouse causal claim</li></ul></article></section>
<section class="card" style="margin-top:16px"><h2>Research-classified subset</h2><p>40 observed research-hire records: 19 Male, 8 Female, 13 Unknown. This is a distinct subset and is not added to the overall 1,095 outcomes.</p><p class="boundary">Feedback coverage: {html.escape(str(data['feedback_coverage']['hiring_observed_coverage']))}. {html.escape(str(data['feedback_coverage']['note']))}</p></section>
<footer class="foot">Study window: 2026-04-01 through 2026-09-30 · Repository destination: <a href="{REPO}">{REPO}</a><br>Presentation layer only. Publication remains on hold pending licensing/privacy review. D3.js loads from its public CDN when online.</footer>
</main><script id="evidence" type="application/json">{payload}</script><script>
const E=JSON.parse(document.getElementById('evidence').textContent);
function bars(selector,items,max,colorFn){{const w=700,h=210,left=150,right=28,top=12,bottom=30;const svg=d3.select(selector).append('svg').attr('viewBox',`0 0 ${{w}} ${{h}}`).attr('width','100%').attr('height','210');const x=d3.scaleLinear().domain([0,max]).range([left,w-right]);const y=d3.scaleBand().domain(items.map(d=>d.name)).range([top,h-bottom]).padding(.23);svg.selectAll('text.label').data(items).join('text').attr('class','label').attr('x',left-10).attr('y',d=>y(d.name)+y.bandwidth()/2+4).attr('text-anchor','end').attr('fill','#12203c').attr('font-size',13).text(d=>d.name);svg.selectAll('rect').data(items).join('rect').attr('x',left).attr('y',d=>y(d.name)).attr('height',y.bandwidth()).attr('width',d=>x(d.value)-left).attr('rx',7).attr('fill',d=>colorFn(d));svg.selectAll('text.value').data(items).join('text').attr('class','value').attr('x',d=>x(d.value)+7).attr('y',d=>y(d.name)+y.bandwidth()/2+4).attr('fill','#12203c').attr('font-size',13).attr('font-weight',700).text(d=>d.value.toLocaleString());}}
bars('#outcome-chart',[{{name:'Male',value:E.observed_outcomes.male}},{{name:'Female',value:E.observed_outcomes.female}},{{name:'Unknown',value:E.observed_outcomes.unknown}}],650,d=>d.name==='Male'?'#547a47':d.name==='Female'?'#547ca8':'#b4933e');
bars('#posting-chart',[{{name:'In-window dated',value:E.greenhouse_postings.established_dates_in_window}},{{name:'Archive-only',value:E.greenhouse_postings.archive_capture_only}},{{name:'Outside window',value:E.greenhouse_postings.outside_window}}],650,d=>d.name==='In-window dated'?'#547a47':d.name==='Archive-only'?'#b4933e':'#547ca8');
</script></body></html>'''
dashboard=OUT/"final_executive_dashboard_d3.html"; dashboard.write_text(doc,encoding="utf-8")
manifest={"status":"BUILT_FROM_CONSOLIDATED_FROZEN_EVIDENCE","dashboard":str(dashboard),"evidence_file":str(evidence_path),"dashboard_sha256":hashlib.sha256(dashboard.read_bytes()).hexdigest(),"evidence_sha256":hashlib.sha256(evidence_path.read_bytes()).hexdigest(),"d3_external_dependency":"https://d3js.org/d3.v7.min.js","external_network_required_for_charts":True,"publication_status":data["publication_status"],"github_repository_destination":REPO,"github_publish_performed":False,"generated_at_utc":datetime.now(timezone.utc).isoformat()}
(OUT/"final_executive_dashboard_d3_manifest.json").write_text(json.dumps(manifest,indent=2),encoding="utf-8")
print("VERSION C — 10 FINAL D3 EXECUTIVE DASHBOARD"); print("STATUS: BUILT"); print(f"DASHBOARD: {dashboard}"); print(f"MANIFEST: {OUT/'final_executive_dashboard_d3_manifest.json'}"); print("PUBLICATION STATUS: HOLD / REVIEW REQUIRED")
